/**
 * URL of an exercise's technique GIF, derived from its image: "/press_banca.jpg" -> "/gifs/press_banca.gif".
 * The GIFs are generated by scripts/generate-exercise-gifs.mjs into public/gifs. Exercises without a
 * generated GIF (or with an external/absent image) return null, or a URL that 404s — the caller hides it
 * on load error.
 */
export function exerciseGifUrl(imageUrl: string | null | undefined): string | null {
  if (!imageUrl || !imageUrl.startsWith("/")) return null;
  const file = imageUrl.split("/").pop() ?? "";
  const base = file.replace(/\.[^.]+$/, "");
  return base ? `/gifs/${base}.gif` : null;
}
